"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    # Collect all nodes: explicit keys and implicit leaves
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    if not all_nodes:
        return []

    # Build normalized graph with implicit leaves and deduplicated dependencies
    normalized = {}
    for node in all_nodes:
        if node in graph:
            deps = list(dict.fromkeys(graph[node]))  # Deduplicate, preserve order
            normalized[node] = deps
        else:
            normalized[node] = []

    # Detect cycles using DFS
    cycles = _find_all_cycles(normalized, all_nodes)
    if cycles:
        best_cycle = _select_best_cycle(cycles)
        raise CycleError(best_cycle)

    # Topological sort using Kahn's algorithm with lexicographic tie-breaking
    in_degree = {node: 0 for node in all_nodes}
    adjacency = {node: [] for node in all_nodes}

    for node, deps in normalized.items():
        for dep in deps:
            adjacency[dep].append(node)
            in_degree[node] += 1

    result = []
    ready = sorted([node for node in all_nodes if in_degree[node] == 0])

    while ready:
        node = ready.pop(0)  # Always take lexicographically smallest
        result.append(node)

        new_ready = []
        for dependent in adjacency[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                new_ready.append(dependent)

        ready.extend(new_ready)
        ready.sort()  # Keep sorted for tie-breaking at every step

    return result


def _find_all_cycles(graph: dict[str, list[str]], all_nodes: set[str]) -> list[list[str]]:
    """Find all cycles in the dependency graph using DFS."""
    color = {node: 0 for node in all_nodes}  # 0=white, 1=gray, 2=black
    cycles = []

    def dfs(node: str, path: list[str]) -> None:
        color[node] = 1  # Mark as gray (in current recursion path)
        path.append(node)

        for dep in graph.get(node, []):
            if color[dep] == 1:  # Back edge found - cycle detected
                idx = path.index(dep)
                cycles.append(path[idx:])
            elif color[dep] == 0:  # White node - recurse
                dfs(dep, path)

        path.pop()
        color[node] = 2  # Mark as black (finished)

    for node in all_nodes:
        if color[node] == 0:
            dfs(node, [])

    return cycles


def _normalize_cycle(cycle: list[str]) -> list[str]:
    """Rotate cycle to start at lexicographically smallest member."""
    if not cycle:
        return cycle
    min_idx = cycle.index(min(cycle))
    return cycle[min_idx:] + cycle[:min_idx]


def _select_best_cycle(cycles: list[list[str]]) -> list[str]:
    """Select the cycle to report based on: shortest, then rotated form, then lexicographic."""
    if not cycles:
        return []

    # Sort by: length first, then normalized form
    sorted_cycles = sorted(cycles, key=lambda c: (len(c), _normalize_cycle(c)))
    # Return the normalized form of the best cycle
    return _normalize_cycle(sorted_cycles[0])
